t.script:

(function () {
    function initPaymentModal() {
        var root = document.querySelector(".ut-checkout-page");
        if (!root) {
            return;
        }

        var modal = root.querySelector("[data-payment-modal]");
        var openButtons = root.querySelectorAll("[data-payment-open]");
        var closeButtons = root.querySelectorAll("[data-payment-close]");
        var choices = root.querySelectorAll("[data-payment-choice]");
        var applyButton = root.querySelector("[data-payment-apply]");
        var hiddenInput = root.querySelector("[data-payment-method-input]");
        var visibleLabel = root.querySelector("[data-payment-label]");
        var selectedValue = hiddenInput ? hiddenInput.value : "bca_va";
        var selectedLabel = visibleLabel ? visibleLabel.textContent.trim() : "BCA Virtual Account";

        function openModal(ev) {
            if (ev) {
                ev.preventDefault();
            }
            if (!modal) {
                return;
            }
            modal.classList.add("is-open");
            modal.setAttribute("aria-hidden", "false");
            document.body.classList.add("ut-payment-modal-open");
        }

        function closeModal(ev) {
            if (ev) {
                ev.preventDefault();
            }
            if (!modal) {
                return;
            }
            modal.classList.remove("is-open");
            modal.setAttribute("aria-hidden", "true");
            document.body.classList.remove("ut-payment-modal-open");
        }

        function selectChoice(button) {
            choices.forEach(function (choice) {
                choice.classList.toggle("is-active", choice === button);
            });
            selectedValue = button.dataset.paymentValue || selectedValue;
            selectedLabel = button.dataset.paymentLabelValue || selectedLabel;
        }

        openButtons.forEach(function (button) {
            button.addEventListener("click", openModal);
        });
        closeButtons.forEach(function (button) {
            button.addEventListener("click", closeModal);
        });
        choices.forEach(function (button) {
            button.addEventListener("click", function (ev) {
                ev.preventDefault();
                selectChoice(button);
            });
        });
        if (applyButton) {
            applyButton.addEventListener("click", function (ev) {
                ev.preventDefault();
                if (hiddenInput) {
                    hiddenInput.value = selectedValue;
                }
                if (visibleLabel) {
                    visibleLabel.textContent = selectedLabel;
                }
                closeModal();
            });
        }
        document.addEventListener("keydown", function (ev) {
            if (ev.key === "Escape" && modal && modal.classList.contains("is-open")) {
                closeModal(ev);
            }
        });
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initPaymentModal);
    } else {
        initPaymentModal();
    }
}());
